set-variable.value:
#[%dw 2.0 output application/java
var conditions = [ if (!isBlank(attributes.queryParams.accountId)) "Id = '" ++ attributes.queryParams.accountId ++ "'" else null,
if (!isBlank(attributes.queryParams.industryId)) "Industry = '" ++ attributes.queryParams.industryId ++ "'" else null ] filter ($ != null)
--- "SELECT Id, Name, AccountNumber, Industry, Description, BillingStreet FROM Account" ++ (if (sizeOf(conditions) > 0) " WHERE " ++ (conditions joinBy " AND ") else "")]
